" fill="#581c87">Meeting</text>\n    <circle cx="100" cy="35" r="15" fill="#9333ea"/>\n    <text x="100" y="39" text-anchor="middle" font-family="sans-serif" font-size="9" font-weight="bold" fill="#ffffff">2</text>\n    <text x="100" y="70" text-anchor="middle" font-family="sans-serif" font-size="8" fill="#581c87">Common Hobbies</text>\n    <circle cx="180" cy="35" r="15" fill="#7e22ce"/>\n    <text x="180" y="39" text-anchor="middle" font-family="sans-serif" font-size="9" font-weight="bold" fill="#ffffff">3</text>\n    <text x="180" y="70" text-anchor="middle" font-family="sans-serif" font-size="8" fill="#581c87">Open Talks</text>\n    <circle cx="260" cy="35" r="15" fill="#6b21a8"/>\n    <text x="260" y="39" text-anchor="middle" font-family="sans-serif" font-size="9" font-weight="bold" fill="#ffffff">4</text>\n    <text x="260" y="70" text-anchor="middle" font-family="sans-serif" font-size="8" fill="#581c87">Support</text>\n    <circle cx="340" cy="35" r="15" fill="#581c87"/>\n    <text x="340" y="39" text-anchor="middle" font-family="sans-serif" font-size="9" font-weight="bold" fill="#ffffff">5</text>\n    <text x="340" y="70" text-anchor="middle" font-family="sans-serif" font-size="8" fill="#581c87">Solid Trust</text>\n  </g>\n</svg>', 6: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 180" width="100%" height="100%">\n  <rect width="100%" height="100%" fill="#fef2f2" rx="8"/>\n  <text x="200" y="24" text-anchor="middle" font-family="sans-serif" font-size="12" font-weight="bold" fill="#991b1b">Idiom in Context: \'See eye to eye\'</text>\n  <g transform="translate(60, 50)">\n    <rect x="0" y="0" width="280" height="70" rx="8" fill="#fee2e2" stroke="#ef4444" stroke-width="1.5"/>\n    <text x="140" y="30" text-anchor="middle" font-family="sans-serif" font-size="12" font-weight="bold" fill="#b91c1c">\'See eye to eye with someone\'</text>\n    <text x="140" y="55" text-anchor="middle" font-family="sans-serif" font-size="10" fill="#991b1b">Meaning: To agree